SELECT COUNT(*) FROM flights WHERE DestAirport IN (SELECT AirportCode FROM airports WHERE City = 'Aberdeen' OR City = 'Abilene')
SELECT airports.AirportName FROM airports WHERE airports.CountryAbbrev NOT IN (SELECT CountryAbbrev FROM flights)
SELECT airports.AirportCode FROM airports WHERE airports.AirportCode NOT IN (SELECT flights.DestAirport FROM flights)
SELECT Name FROM employee ORDER BY Age ASC;
SELECT Name, Age FROM employee ORDER BY Age ASC
SELECT City, COUNT(*) AS TotalEmployees FROM employee JOIN hiring ON hiring.Employee_ID = employee.Employee_ID GROUP BY City HAVING COUNT(*) > 1 AND Age < 30;
SELECT e.City FROM employee e JOIN hiring h ON e.Employee_ID = h.Employee_ID WHERE h.Is_full_time = 'Y' AND h.Start_from <= 30 AND e.Age < 30
SELECT COUNT(DISTINCT shop.Shop_ID), shop.City FROM shop JOIN employee ON shop.Manager_name = employee.Name;
SELECT DISTINCT employee.City, COUNT(shop.Shop_ID) AS total_shops FROM employee JOIN shop ON employee.City = shop.Location GROUP BY employee.City;
SELECT e.Manager_name, s.District FROM employee e JOIN shop s ON e.Manager_name = s.Manager_name JOIN hiring h ON h.Shop_ID = s.Shop_ID GROUP BY e.Manager_name ORDER BY s.District DESC LIMIT 1;
SELECT e.Name, s.District FROM employee e JOIN shop s ON e.Manager_name = s.Manager_name ORDER BY s.Number_products DESC;
SELECT e.Name, s.Location, s.District, e.Number_products FROM employee e JOIN shop s ON e.Employee_ID = s.Manager_name ORDER BY s.Number_products DESC;
SELECT employee.Name, shop.Location, shop.District FROM employee INNER JOIN shop ON employee.Employee_ID = shop.Manager_name;
SELECT e.Name AS Name FROM employee e JOIN hiring h ON e.Employee_ID = h.Employee_ID JOIN shop s ON h.Shop_ID = s.Shop_ID WHERE s.Number_products > (SELECT AVG(Number_products) FROM shop)
SELECT Name FROM shop WHERE Number_products > (SELECT AVG(Number_products) FROM shop)
SELECT e.Name, e.Age, e.City, e.Manager_name FROM employee e JOIN hiring h ON e.Employee_ID = h.Employee_ID JOIN evaluation e2 ON e.Employee_ID = e2.Employee_ID GROUP BY e.Employee_ID ORDER BY e2.Bonus DESC;
SELECT Name FROM employee ORDER BY Bonus DESC LIMIT 1
SELECT e.Name, h.Shop_ID FROM employee e JOIN hiring h ON e.Employee_ID = h.Employee_ID WHERE h.Is_full_time = TRUE ORDER BY h.Number_products DESC LIMIT 1
SELECT Name FROM shop ORDER BY Number_products DESC LIMIT 1;
SELECT Name FROM shop WHERE Manager_name IS NULL
SELECT Name FROM shop WHERE Manager_name IS NULL
SELECT District FROM shop WHERE District IN (SELECT District FROM shop WHERE Number_products < 3000 AND District IN (SELECT District FROM shop WHERE Number_products > 10000))
SELECT DISTINCT District FROM shop WHERE Number_products < 3000 AND Number_products > 10000;
SELECT Name, Age FROM teacher ORDER BY Age ASC;
SELECT Name, Age FROM teacher ORDER BY Age ASC;
SELECT teacher.Name FROM teacher JOIN course_arrange ON course_arrange.Course_ID = course.Course_ID JOIN course ON course.Course_ID = course_arrange.Course_ID WHERE teacher.Hometown != 'Little Lever Urban District'
SELECT teacher.Name FROM teacher JOIN course_arrange ON course_arrange.Course_ID = course.Course_ID WHERE course_arrange.Teacher_ID != teacher.Teacher_ID
SELECT teacher.Name FROM teacher WHERE teacher.Age = 32 OR teacher.Age = 33;
SELECT Name FROM teacher WHERE Age = 32 OR Age = 33;
SELECT DISTINCT teacher.Hometown FROM teacher JOIN course_arrange ON teacher.Teacher_ID = course_arrange.Teacher_ID WHERE course_arrange.Course_ID IN (SELECT Course_ID FROM course WHERE Course = '101')
SELECT DISTINCT teacher.Name, teacher.Age, teacher.Hometown FROM teacher JOIN course_arrange ON course_arrange.Teacher_ID = teacher.Teacher_ID WHERE course_arrange.Course_ID = (SELECT Course_ID FROM course ORDER BY Course_ID ASC LIMIT 1)
SELECT DISTINCT teacher.Hometown, COUNT(teacher.Teacher_ID) AS total_teachers FROM teacher JOIN course_arrange ON course_arrange.Teacher_ID = teacher.Teacher_ID GROUP BY teacher.Hometown;
SELECT DISTINCT teacher.Hometown, COUNT(teacher.Hometown) AS total_teachers_per_place FROM course_arrange JOIN teacher ON course_arrange.Teacher_ID = teacher.Teacher_ID GROUP BY teacher.Hometown
SELECT DISTINCT teacher.Name, teacher.Hometown FROM teacher JOIN course_arrange ON course_arrange.Teacher_ID = teacher.Teacher_ID ORDER BY teacher.Hometown ASC;
SELECT DISTINCT t.Name, t.Hometown FROM teacher t JOIN course_arrange ca ON t.Teacher_ID = ca.Teacher_ID GROUP BY t.Name, t.Hometown ORDER BY t.Name
SELECT teacher.Name FROM teacher JOIN course_arrange ON teacher.Teacher_ID = course_arrange.Teacher_ID WHERE course_arrange.Course_ID IN (SELECT Course_ID FROM course WHERE Course = 'math')
SELECT Name FROM teacher WHERE Age IS NULL OR Hometown IS NULL;
SELECT teacher.Name FROM teacher JOIN course_arrange ON course_arrange.Course_ID = course.Course_ID WHERE course_arrange.Teacher_ID NOT IN (SELECT Teacher_ID FROM course_arrange)
SELECT teacher.Name FROM teacher INNER JOIN course_arrange ON course_arrange.Course_ID = course.Course_ID WHERE course_arrange.Teacher_ID IS NULL
SELECT COUNT(DISTINCT visitor.ID) FROM visitor WHERE Level_of_membership < '30'
SELECT visitor.Name FROM visitor JOIN visit ON visit.visitor_ID = visitor.ID WHERE visit.Level_of_membership > 4 ORDER BY Level_of_membership DESC;
SELECT AVG(visitor.Age) FROM visitor INNER JOIN visit ON visit.visitor_ID = visitor.ID WHERE visit.Museum_ID = museum.Museum_ID AND visitor.Level_of_membership <= 4
SELECT museum.Museum_ID, museum.Name, COUNT(visitor.visitor_ID) AS total_visitors FROM museum JOIN visit ON museum.Museum_ID = visit.Museum_ID GROUP BY museum.Museum_ID ORDER BY total_visitors DESC;
SELECT AVG(museum.Num_of_Staff) FROM museum JOIN visit ON museum.Museum_ID = visit.Museum_ID WHERE visit.Open_Year < '2009'
SELECT museum.Open_Year, museum.Num_of_Staff FROM museum;
SELECT Name FROM museum WHERE Num_of_Staff > (SELECT MIN(Num_of_Staff) FROM museum WHERE Open_Year > '2010')
SELECT v.ID, v.Name, v.Age FROM visitor v JOIN visit v2 ON v.ID = v2.visitor_ID JOIN museum ON v2.Museum_ID = museum.Museum_ID WHERE v2.Num_of_Ticket > 0;
SELECT id, name, membership_level FROM visitor INNER JOIN visit ON visit.visitor_ID = visitor.ID WHERE visit.Total_spent = (SELECT MAX(Num_of_Ticket * Total_spent) FROM visit)
SELECT museum.Museum_ID, museum.Name, COUNT(visitor.ID) AS num_visitors FROM museum JOIN visit ON museum.Museum_ID = visit.Museum_ID JOIN visitor ON visit.visitor_ID = visitor.ID GROUP BY museum.Museum_ID, museum.Name ORDER BY COUNT(visitor.ID) DESC;
SELECT museum.Name FROM museum INNER JOIN visit ON museum.Museum_ID = visit.Museum_ID WHERE visit.visitor_ID IS NULL;
SELECT v.Name, v.Age FROM visitor v JOIN visit v2 ON v.ID = v2.visitor_ID JOIN museum m ON v2.Museum_ID = m.Museum_ID GROUP BY v.Name, v.Age ORDER BY v.Age DESC LIMIT 1;
SELECT SUM(visit.Total_spent) AS total_ticket_expense FROM visit INNER JOIN museum ON visit.Museum_ID = museum.Museum_ID;
SELECT players.first_name, players.birth_date FROM players JOIN matches ON players.player_id = matches.loser_id WHERE players.country_code = 'USA' ORDER BY players.first_name
SELECT first_name, birth_date FROM players JOIN matches ON players.player_id = matches.loser_id WHERE country_code = 'US' ORDER BY first_name
SELECT tourney_name FROM matches INNER JOIN rankings ON matches.loser_id = rankings.player_id GROUP BY tourney_name HAVING COUNT(*) > 10
SELECT tourney_name FROM matches INNER JOIN rankings ON matches.loser_id = rankings.player_id WHERE matches.tourney_id IS NOT NULL AND matches.tourney_date IS NOT NULL AND matches.best_of > 10
SELECT players.first_name, players.last_name FROM players JOIN matches ON players.player_id = matches.winner_id JOIN rankings ON players.player_id = rankings.player_id WHERE matches.year IN (2013, 2016) GROUP BY players.first_name, players.last_name DISTINCT ORDER BY players.first_name, players.last_name
SELECT p.first_name, p.last_name FROM players p JOIN matches m ON p.player_id = m.winner_id WHERE m.year IN (2013, 2016)
SELECT COUNT(*) FROM players INNER JOIN matches ON players.player_id = matches.loser_id WHERE year IN (2013, 2016)
SELECT COUNT(*) FROM matches WHERE year IN ('2013', '2016')
SELECT p.first_name, p.country_code FROM players p JOIN matches m ON p.player_id = m.winner_id WHERE m.tourney_name IN ('WTA Championships', 'Australian Open')
SELECT p.first_name, p.country_code FROM players p JOIN matches m ON p.player_id = m.winner_id JOIN rankings r ON p.player_id = r.player_id WHERE m.tourney_id = 'WTA Championships' AND m.tourney_id = 'Australian Open'
SELECT players.first_name, players.country_code FROM players JOIN rankings ON players.player_id = rankings.player_id ORDER BY players.player_id ASC LIMIT 1;
SELECT p.first_name, p.country_code FROM players p JOIN rankings r ON p.player_id = r.player_id ORDER BY p.winner_age DESC LIMIT 1;
SELECT players.first_name, players.last_name, matches.loser_age FROM players JOIN matches ON players.player_id = matches.loser_id ORDER BY matches.loser_age ASC;
SELECT first_name, last_name FROM players ORDER BY winner_age ASC;
SELECT p.first_name, p.last_name FROM players p JOIN matches m ON p.player_id = m.loser_id ORDER BY p.age ASC;
SELECT p.first_name, p.last_name, p.hand, p.birth_date, p.country_code FROM players p JOIN matches m ON p.player_id = m.loser_id ORDER BY p.winner_age ASC;
SELECT players.first_name, matches.winner_rank_points AS winner_rank_points FROM players INNER JOIN matches ON players.player_id = matches.winner_id ORDER BY winner_rank_points DESC;
SELECT p.first_name, p.last_name, r.ranking_points FROM players p JOIN rankings r ON p.player_id = r.player_id ORDER BY r.ranking_points DESC LIMIT 1;
SELECT p.first_name, p.last_name, p.country_code FROM players p JOIN rankings r ON p.player_id = r.player_id ORDER BY r.ranking_points DESC LIMIT 1;
SELECT winner_name FROM matches INNER JOIN players ON matches.winner_id = players.player_id WHERE matches.tourney_id = (SELECT tourney_id FROM rankings WHERE ranking = 'Australian Open' AND player_id = (SELECT player_id FROM players WHERE first_name = 'Australian Open' AND last_name = 'Open') LIMIT 1)
SELECT p.first_name, p.last_name FROM players p JOIN matches m ON p.player_id = m.loser_id WHERE m.minutes IS MAX((SELECT minutes FROM matches WHERE match_num = m.match_num))
SELECT p.first_name, p.last_name, m.loser_name FROM players p JOIN matches m ON p.player_id = m.loser_id;
SELECT COUNT(DISTINCT players.player_id) AS total_players, players.country_code AS country FROM players GROUP BY players.country_code;
SELECT DISTINCT country_code, COUNT(*) AS count FROM players GROUP BY country_code;
SELECT country_code FROM players JOIN rankings ON players.player_id = rankings.player_id ORDER BY ranking_points DESC LIMIT 1
SELECT country_code FROM players JOIN matches ON players.player_id = matches.loser_id GROUP BY player_id ORDER BY ranking_points DESC LIMIT 1;
SELECT players.country_code FROM players INNER JOIN matches ON players.player_id = matches.loser_id WHERE matches.round = '2023' AND matches.minutes > 50000
SELECT country_code FROM players JOIN matches ON players.player_id = matches.loser_id WHERE matches.round = '1' AND matches.minutes > 50000;
SELECT p.first_name, p.last_name, r.rankings_points FROM players p JOIN rankings r ON p.player_id = r.player_id ORDER BY r.rankings_points ASC LIMIT 3;
SELECT p.first_name, p.last_name, r.ranking FROM players p JOIN rankings r ON p.player_id = r.player_id ORDER BY r.ranking ASC LIMIT 3
SELECT COUNT(DISTINCT players.player_id) FROM players INNER JOIN matches ON matches.winner_id = players.player_id WHERE players.hand = 'L' AND matches.loser_hand = 'L'
SELECT COUNT(*) FROM players p INNER JOIN matches m ON p.player_id = m.winner_id WHERE p.hand = 'left' AND m.tourney_name = 'WTA Championships'
SELECT COUNT(*) FROM ship WHERE disposition_of_ship = 'Captured'
SELECT b.id, b.name, d.id, d.note, d.killed, d.injured FROM battle b JOIN death d ON b.id = d.caused_by_ship_id WHERE d.killed > 10
SELECT ship.id, ship.name, COUNT(death.injured) AS total_injuries FROM ship JOIN death ON ship.id = death.caused_by_ship_id GROUP BY ship.id, ship.name ORDER BY total_injuries DESC;
SELECT b.name, b.date FROM battle b JOIN ship s ON b.id = s.lost_in_battle WHERE b.latin_commander = 'Lettice' AND b.name = 'HMS Atalanta'
SELECT battle.name, battle.results, battle.bulgarian_commander FROM battle JOIN ship ON battle.id = ship.lost_in_battle WHERE ship.location = 'English Channel' AND battle.result = 'no ships lost'
