SELECT course_description FROM Courses;
SELECT Addresses.zip_postcode FROM Addresses;
SELECT zip_postcode FROM Addresses WHERE city = 'Port Chelsea'
SELECT s.last_name FROM Students s JOIN Addresses a ON s.current_address_id = a.address_id JOIN Departments d ON s.current_address_id = a.state_province_county WHERE a.state_province_county = 'North Carolina' AND s.date_left IS NULL;
SELECT last_name FROM Students WHERE state_province_county = 'North Carolina' AND date_first_registered IS NULL;
SELECT student_id, cell_mobile_number FROM Students WHERE first_name = 'Timmothy' AND last_name = 'Ward';
SELECT student_id, cell_mobile_number FROM Students WHERE first_name = 'Timmothy' AND last_name = 'Ward';
SELECT first_name, middle_name, last_name FROM Students ORDER BY date_first_registered ASC LIMIT 1
SELECT s.first_name, s.middle_name, s.last_name, s.date_first_registered FROM Students s WHERE s.date_first_registered IS NULL ORDER BY s.date_first_registered ASC LIMIT 1
SELECT first_name, middle_name, last_name, first_name, middle_name, last_name FROM Students JOIN Addresses ON Students.current_address_id = Addresses.address_id JOIN Courses ON Students.current_address_id = Addresses.address_id JOIN Sections ON Students.current_address_id = Addresses.address_id JOIN Transcripts ON Students.current_address_id = Transcripts.transcript_date JOIN Transcript_Contents ON Transcript_Contents.student_course_id = Sections.section_id JOIN Degree_Programs ON Sections.section_id = Degree_Programs.department_id JOIN Departments ON Degree_Programs.department_id = Departments.department_id WHERE Semester_id = (SELECT semester_id FROM Semesters ORDER BY semester_id LIMIT 1) ORDER BY last_name
SELECT s.id, s.first_name, s.middle_name, s.last_name, s.cell_mobile_number, s.email_address, s.ssn, s.date_first_registered, s.date_left, s.other_student_details FROM Students s JOIN Student_Enrolment_Courses sc ON s.id = sc.student_course_id JOIN Courses c ON sc.course_id = c.course_id JOIN Sections s2 ON s.section_id = s2.section_id JOIN Semesters s3 ON s2.semester_id = s3.semester_id JOIN Departments d ON s2.department_id = d.department_id JOIN Degree_Programs dp ON s2.degree_program_id = dp.degree_program_id JOIN Transcript_Contents tc ON s2.student_id = tc.student_course_id JOIN Transcripts t ON tc.transcript_id = t.transcript_id JOIN Transcript_Contents tc2 ON s2.student_id = tc2.student_course_id;
SELECT Addresses.id, Addresses.line_1, Addresses.line_2 FROM Addresses INNER JOIN Students ON Addresses.address_id = Students.current_address_id WHERE Students.date_left IS NULL;
SELECT DISTINCT Semesters.semester_name AS semester FROM Semesters JOIN Students ON Students.student_id = Semesters.semester_id;
SELECT DISTINCT S.semester_id FROM Semesters S JOIN Students S2 ON S.semester_id = S2.date_left JOIN Addresses A ON S2.current_address_id = A.address_id JOIN Students S3 ON S2.permanent_address_id = A.address_id JOIN Addresses A2 ON S3.permanent_address_id = A2.address_id;
SELECT s.first_name FROM Students s WHERE s.permanent_address_id = (SELECT address_id FROM Addresses WHERE city = 'Haiti' AND zip_postcode IS NOT NULL) OR s.cell_mobile_number = '09700166582' GROUP BY s.first_name ORDER BY s.first_name ASC
SELECT s.first_name, s.middle_name, s.last_name FROM Students s WHERE s.cell_mobile_number = '09700166582' OR s.permanent_address_id IS NOT NULL;
