SELECT Professionals.professional_id, Professionals.last_name, Professionals.cell_number FROM Professionals INNER JOIN Dogs ON Dogs.owner_id = Professionals.owner_id WHERE Professionals.state = 'Indiana' OR Professionals.cell_number IS NOT NULL;
SELECT Professionals.professional_id, Professionals.last_name, Professionals.cell_number FROM Professionals INNER JOIN Owners ON Professionals.owner_id = Owners.owner_id INNER JOIN Dogs ON Dogs.owner_id = Owners.owner_id INNER JOIN Treatments ON Treatments.dog_id = Dogs.dog_id INNER JOIN Treatment_Types ON Treatments.treatment_type_code = Treatment_Types.treatment_type_code WHERE Professionals.state = 'Indiana' OR Treatments.date_of_treatment > 0;
SELECT Dogs.name, Owners.first_name, Owners.last_name FROM Dogs INNER JOIN Owners ON Dogs.owner_id = Owners.owner_id WHERE Dogs.treatment_type_code IS NULL OR Charges.charge_amount > 1000;
SELECT o.first_name, o.last_name, o.owner_id FROM Owners o JOIN Dogs d ON o.owner_id = d.owner_id ORDER BY d.age DESC LIMIT 1;
SELECT Dogs.owner_id, Dogs.first_name, Dogs.last_name FROM Dogs INNER JOIN Owners ON Dogs.owner_id = Owners.owner_id ORDER BY Dogs.age DESC LIMIT 1;
SELECT Dogs.dog_id, Professionals.first_name, Dogs.name FROM Dogs INNER JOIN Professionals ON Dogs.owner_id = Professionals.owner_id WHERE Dogs.abandoned_yn = 'Y' OR Dogs.dog_id = Professionals.professional_id GROUP BY Dogs.dog_id, Professionals.first_name, Dogs.name
SELECT Dogs.dog_id, Dogs.name, Professionals.first_name, Professionals.role_code FROM Dogs INNER JOIN Professionals ON Dogs.owner_id = Professionals.owner_id WHERE Dogs.dog_id IN (SELECT Dogs.dog_id FROM Charges INNER JOIN Dogs ON Charges.charge_id = Dogs.charge_id GROUP BY Dogs.dog_id HAVING COUNT(Dogs.dog_id) > 1)
SELECT t.treatment_type_description, t.cost_of_treatment FROM Treatments t JOIN Treatment_Types ON t.treatment_type_code = t.treatment_type_code;
SELECT treatment_type_description FROM Treatment_Types ORDER BY cost_of_treatment ASC LIMIT 1;
SELECT o.owner_id, o.zip_code, d.dog_id, d.date_departed, d.date_arrived, d.name, d.age, d.date_of_birth, d.gender, d.weight, d.date_of_birth, d.date_departed, d.date_arrived FROM Owners o JOIN Dogs d ON o.owner_id = d.owner_id JOIN Treatments t ON d.dog_id = t.dog_id JOIN Treatment_Types t1 ON t.treatment_type_code = t1.treatment_type_code JOIN Sizes s ON d.size_code = s.size_code JOIN Breeds b ON d.breed_code = b.breed_code JOIN Professionals p ON t.professional_id = p.professional_id WHERE t.cost_of_treatment IS NOT NULL AND t.date_of_treatment IS NOT NULL ORDER BY d.date_departed DESC;
SELECT Dogs.id, Dogs.zip_code FROM Dogs INNER JOIN Owners ON Dogs.owner_id = Owners.owner_id INNER JOIN Treatments ON Treatments.dog_id = Dogs.dog_id INNER JOIN Professionals ON Treatments.professional_id = Professionals.professional_id INNER JOIN Treatment_Types ON Treatments.treatment_type_code = Treatment_Types.treatment_type_code GROUP BY Dogs.id, Dogs.zip_code ORDER BY SUM(Dogs.weight) DESC LIMIT 1;
SELECT o.first_name, o.last_name FROM Owners o JOIN Professionals p ON o.owner_id = p.owner_id JOIN Dogs d ON d.owner_id = o.owner_id JOIN Treatments t ON d.dog_id = t.dog_id JOIN Treatment_Types t1 ON t.treatment_type_code = t1.treatment_type_code WHERE t.cost_of_treatment < t1.cost_of_treatment;
SELECT o.first_name, o.last_name FROM Owners o JOIN Dogs d ON o.owner_id = d.owner_id JOIN Professionals p ON p.professional_id = d.professional_id JOIN Treatment_Types t ON d.treatment_type_code = t.treatment_type_code JOIN Sizes s ON d.size_code = s.size_code WHERE t.size_description = 'smaller' AND t.treatment_type_code = (SELECT treatment_type_code FROM Treatment_Types WHERE treatment_type_description = 'treatment') GROUP BY o.first_name, o.last_name;
SELECT Dogs.name, Owners.first_name FROM Dogs INNER JOIN Owners ON Dogs.owner_id = Owners.owner_id WHERE Owners.state = 'Virginia' AND Owners.street IS NOT NULL;
SELECT Dogs.name, Owners.first_name FROM Dogs INNER JOIN Owners ON Dogs.owner_id = Owners.owner_id WHERE Owners.state = 'Virginia' AND Dogs.abandoned_yn = 'N' AND Dogs.breed_code = Breeds.breed_code;
SELECT Dogs.owner_id, Owners.last_name FROM Dogs INNER JOIN Owners ON Dogs.owner_id = Owners.owner_id WHERE Dogs.age = (SELECT MIN(age) FROM Dogs)
SELECT Owners.last_name, Dogs.age FROM Dogs INNER JOIN Owners ON Dogs.owner_id = Owners.owner_id ORDER BY Dogs.age ASC LIMIT 1;
SELECT o.email_address FROM Owners o JOIN Dogs d ON o.owner_id = d.owner_id JOIN Professionals p ON d.professional_id = p.professional_id WHERE o.state = 'Hawaii' OR o.state = 'Wisconsin';
SELECT email_address FROM Professionals INNER JOIN Owners ON Professionals.owner_id = Owners.owner_id WHERE Owners.state = 'Hawaii' OR Owners.state = 'Wisconsin' AND email_address IS NOT NULL;
SELECT COUNT(DISTINCT Dogs.age) FROM Dogs;
SELECT COUNT(DISTINCT Dogs.age) FROM Dogs;
