SELECT property_name, property_address, room_count, apt_feature_1, apt_feature_2, apt_feature_3, fld_feature_1, fld_feature_2, fld_feature_3, hse_feature_1, hse_feature_2, hse_feature_3, oth_feature_1, oth_feature_2, oth_feature_3, other_property_details FROM Properties WHERE property_type_code = 'apt' OR property_type_code = 'house' AND room_count > 1;
